def test_to_dense_backward_ignores_input_metadata():
    # Only input's dtype matters for a strided input: a transposed / sliced /
    # expanded input yields the same result as a contiguous one of the same
    # dtype. The native operator returns `grad` itself when dtypes match even
    # when input is a non-contiguous view.
    grad = torch.randn(6, 7, device=flag_gems.device, dtype=torch.float32)
    for input in (
        torch.randn(6, 7, device=flag_gems.device, dtype=torch.float16),
        torch.randn(7, 6, device=flag_gems.device, dtype=torch.float16).t(),
        torch.randn(6, 7, device=flag_gems.device, dtype=torch.float16)[::2, ::2],
    ):
        actual, expected = _assert_dense(grad, input)
        assert actual.shape == expected.shape


